debug.error_function_source:
async def act(page):
    """
    From the current New Product page (document title exactly as in the accessibility tree),
    complete the remaining required fields for the simple product:
      - Set Price = 769.99 (Prices section)
      - Set Color = Black (combobox .select_option)
      - Set Size = uni-size (combobox .select_option)
      - Open Inventory and set Qty = 42 and Stock Availability = In Stock
      - Click Save (final action)

    All locators are scoped from the exact top-level document node to avoid ambiguity.
    """
    import asyncio

    async def safe_click(locator, timeout=3000):
        try:
            await locator.click(timeout=timeout)
            return True
        except Exception:
            return False

    async def safe_fill(locator, value, timeout=3000):
        try:
            await locator.fill(value, timeout=timeout)
            return True
        except Exception:
            return False

    async def safe_select(locator, **kwargs):
        try:
            await locator.select_option(**kwargs)
            return True
        except Exception:
            return False

    # Top-level document node (exact name from accessibility tree)
    doc = page.get_by_role(
        "document",
        name="New Product / Manage Products / Catalog / Magento Admin",
    )

    # Note on knowledge-base functions: the provided <functions> block is empty, so there
    # are no KB functions to call. All interactions use Playwright APIs directly.

    # 1) Click Prices to reveal/set the Price field (if needed)
    await safe_click(doc.get_by_role("link", name="Prices"))
    await page.wait_for_timeout(400)

    # 2) Fill Price = 769.99. Try direct textbox first, then fall back to scanning textboxes
    price_set = False
    try:
        price_box = doc.get_by_role("textbox", name="Price")
        price_set = await safe_fill(price_box, "769.99")
    except Exception:
        price_set = False

    if not price_set:
        try:
            all_textboxes = page.get_by_role("textbox")
            count = await all_textboxes.count()
            for i in range(count):
                try:
                    tb = all_textboxes.nth(i)
                    a_name = (await tb.get_attribute('aria-label')) or (await tb.get_attribute('name')) or ''
                    if 'price' in a_name.lower():
                        if await safe_fill(tb, '769.99'):
                            price_set = True
                            break
                except Exception:
                    continue
        except Exception:
            pass

    # 3) Set Color -> Black via combobox (.select_option required)
    color_set = False
    try:
        color_comb = doc.get_by_role("combobox", name="Color")
        color_set = await safe_select(color_comb, label="Black")
    except Exception:
        color_set = False

    if not color_set:
        try:
            all_combs = page.get_by_role("combobox")
            cnt = await all_combs.count()
            for j in range(cnt):
                try:
                    c = all_combs.nth(j)
                    if await safe_select(c, label="Black"):
                        color_set = True
                        break
                except Exception:
                    continue
        except Exception:
            pass

    # 4) Set Size -> try several common uni-size labels via combobox
    size_set = False
    size_labels = ["uni-size", "Uni-Size", "Uni Size", "uni size", "Uni"]
    try:
        size_comb = doc.get_by_role("combobox", name="Size")
        for lbl in size_labels:
            if await safe_select(size_comb, label=lbl):
                size_set = True
                break
    except Exception:
        size_set = False

    if not size_set:
        try:
            all_combs = page.get_by_role("combobox")
            cnt = await all_combs.count()
            for j in range(cnt):
                try:
                    c = all_combs.nth(j)
                    for lbl in size_labels:
                        try:
                            if await safe_select(c, label=lbl):
                                size_set = True
                                break
                        except Exception:
                            continue
                    if size_set:
                        break
                except Exception:
                    continue
        except Exception:
            pass

    # 5) Inventory: click Inventory then set Qty = 42 and Stock Availability = In Stock
    await safe_click(doc.get_by_role("link", name="Inventory"))
    await page.wait_for_timeout(400)

    qty_set = False
    for qty_name in ["Qty", "Quantity", "qty"]:
        try:
            tb = doc.get_by_role("textbox", name=qty_name)
            if await safe_fill(tb, "42"):
                qty_set = True
                break
        except Exception:
            try:
                sp = doc.get_by_role("spinbutton", name=qty_name)
                if await safe_fill(sp, "42"):
                    qty_set = True
                    break
            except Exception:
                continue

    if not qty_set:
        try:
            all_textboxes = page.get_by_role("textbox")
            cnt = await all_textboxes.count()
            for i in range(cnt):
                try:
                    tb = all_textboxes.nth(i)
                    a_name = (await tb.get_attribute('aria-label')) or (await tb.get_attribute('name')) or ''
                    if 'qty' in a_name.lower() or 'quantity' in a_name.lower():
                        if await safe_fill(tb, '42'):
                            qty_set = True
                            break
                except Exception:
                    continue
        except Exception:
            pass

    # Stock Availability -> In Stock
    stock_set = False
    try:
        stock_comb = doc.get_by_role("combobox", name="Stock Availability")
        stock_set = await safe_select(stock_comb, label="In Stock")
    except Exception:
        stock_set = False

    if not stock_set:
        try:
            all_combs = page.get_by_role("combobox")
            cnt = await all_combs.count()
            for j in range(cnt):
                try:
                    c = all_combs.nth(j)
                    if await safe_select(c, label="In Stock"):
                        stock_set = True
                        break
                except Exception:
                    continue
        except Exception:
            pass

    # 6) Final action: click Save (this will submit & navigate away)
    try:
        save_btn = doc.get_by_role("button", name="Save")
        await save_btn.click()
    except Exception:
        try:
            # fallback: any button with 'save' in text
            buttons = page.get_by_role("button")
            cnt = await buttons.count()
            for i in range(cnt):
                try:
                    b = buttons.nth(i)
                    txt = (await b.inner_text()).lower()
                    if 'save' in txt:
                        await b.click()
                        break
                except Exception:
                    continue
        except Exception:
            pass

    return

